#include <stdio.h>
#include <string.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    char word[20];
    int i;
    for (i = 0; i < n; i++) {
        int code;
        if (scanf("%d", &code) != 1) {
            return 1;
        }
        word[i] = (char)code;
    }
    word[n] = '\0';

    printf("%s\n", word);
    printf("一共 %d 颗珠子\n", (int)strlen(word));
    return 0;
}
